class Solution {
    public long findTheArrayConcVal(int[] nums) {
        long answer = 0;
        int left = 0;
        int right = nums.length - 1;
        while (left <= right) {
            if (left == right) {
                answer += nums[left];
            } else {
                answer += concatenate(nums[left], nums[right]);
            }
            left++;
            right--;
        }
        return answer;
    }

    private long concatenate(int leftValue, int rightValue) {
        int multiplier = 10;
        int value = rightValue;
        while (value >= 10) {
            multiplier *= 10;
            value /= 10;
        }
        return (long) leftValue * multiplier + rightValue;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public long findTheArrayConcVal(int[] nums) {
        Deque<Integer> deque = new ArrayDeque<>();
        for (int num : nums) {
            deque.offerLast(num);
        }
        long answer = 0;
        while (deque.size() > 1) {
            int leftValue = deque.pollFirst();
            int rightValue = deque.pollLast();
            answer += Long.parseLong(String.valueOf(leftValue) + rightValue);
        }
        if (!deque.isEmpty()) {
            answer += deque.pollFirst();
        }
        return answer;
    }
}

class Solution {
    public long findTheArrayConcVal(int[] nums) {
        return solve(nums, 0, nums.length - 1);
    }

    private long solve(int[] nums, int left, int right) {
        if (left > right) {
            return 0;
        }
        if (left == right) {
            return nums[left];
        }
        return concatenate(nums[left], nums[right]) + solve(nums, left + 1, right - 1);
    }

    private long concatenate(int leftValue, int rightValue) {
        int multiplier = 10;
        int value = rightValue;
        while (value >= 10) {
            multiplier *= 10;
            value /= 10;
        }
        return (long) leftValue * multiplier + rightValue;
    }
}

class Solution {
    public long findTheArrayConcVal(int[] nums) {
        long answer = 0;
        int left = 0;
        int right = nums.length - 1;
        while (left <= right) {
            if (left == right) {
                answer += nums[left];
            } else {
                int multiplier = multiplierFor(nums[right]);
                answer += (long) nums[left] * multiplier + nums[right];
            }
            left++;
            right--;
        }
        return answer;
    }

    private int multiplierFor(int value) {
        if (value < 10) {
            return 10;
        }
        if (value < 100) {
            return 100;
        }
        if (value < 1000) {
            return 1000;
        }
        if (value < 10000) {
            return 10000;
        }
        if (value < 100000) {
            return 100000;
        }
        return 1000000;
    }
}
